"""Edge-case tests for figure-api — generated by bug-hunter agent.

Focus areas:
- configure() with figure-level functions (displot, catplot, lmplot, etc.)
- annotations on figure-level charts
- structural features on figure-level charts
- configure() parameter validation and cascade
- Interaction between configure() and themes
- Empty/degenerate inputs to figure-level functions
- Null/NaN propagation through figure functions
- Composition corners (configure + annotation + structural stacking)
"""
from __future__ import annotations

import json
import math

import polars as pl
import pytest

import ferrum as fm
from ferrum.configure import (
    AxisConfig,
    ColorConfig,
    Configure,
    GridConfig,
    LegendConfig,
    PaddingConfig,
    TitleConfig,
)
from ferrum.structural import BreakAxis, Inset, SecondaryY
import ferrum.annotation as ann
from ferrum.annotation import Annotate


