# ===================================================================
# Category: Configure validation
# ===================================================================


class TestConfigureValidation:
    """Tests targeting AxisConfig, LegendConfig, TitleConfig __post_init__
    validation in configure.py lines 109-118, 164-169, 206-211.
    """

    def test_axis_config_mutually_exclusive_formats(self):
        """AxisConfig.__post_init__ line 110: label_format and label_format_raw
        are mutually exclusive; passing both must raise ValueError."""
        with pytest.raises(ValueError, match="mutually exclusive"):
            AxisConfig(label_format="percent", label_format_raw=".2f")

    def test_axis_config_unknown_format_preset(self):
        """AxisConfig.__post_init__ line 116: unknown label_format must raise
        via resolve_format."""
        with pytest.raises(ValueError, match="Unknown format preset"):
            AxisConfig(label_format="nonexistent_format_preset_xyz")

    def test_legend_config_invalid_orient(self):
        """LegendConfig.__post_init__ line 165: orient must be in _VALID_LEGEND_ORIENTS."""
        with pytest.raises(ValueError, match="orient"):
            LegendConfig(orient="invalid_orient")

    def test_title_config_invalid_anchor(self):
        """TitleConfig.__post_init__ line 207: anchor must be in _VALID_TITLE_ANCHORS."""
        with pytest.raises(ValueError, match="anchor"):
            TitleConfig(anchor="invalid_anchor")

    def test_break_axis_invalid_axis(self):
        """BreakAxis.__post_init__ line 65: axis must be 'x' or 'y'."""
        with pytest.raises(ValueError, match="'x' or 'y'"):
            BreakAxis(axis="z", gap=(10, 20))

    def test_break_axis_invalid_style(self):
        """BreakAxis.__post_init__ line 68: break_style must be in _VALID_BREAK_STYLES."""
        with pytest.raises(ValueError, match="break_style"):
            BreakAxis(axis="x", gap=(10, 20), break_style="unknown_style")

    def test_inset_invalid_connect_style(self):
        """Inset.__post_init__ line 115: connect_style must be in _VALID_CONNECT_STYLES."""
        dummy_chart = fm.Chart(pl.DataFrame({"x": [1], "y": [2]})).mark_point().encode(x="x", y="y")
        with pytest.raises(ValueError, match="connect_style"):
            Inset(chart=dummy_chart, bounds=(0.1, 0.1, 0.5, 0.5), connect_style="invalid")


# ===================================================================
# Category: Configure cascade / merge
# ===================================================================


class TestConfigureCascade:
    """Tests targeting _resolve_chart_config in _render.py lines 279-296.
    Multiple Configure layers should merge; later keys should win.
    """

    def test_multiple_configure_layers_merge(self, simple_df):
        """_resolve_chart_config line 284-288: later configure keys override earlier."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_angle=-45)
            .configure_axis(label_angle=-90)
        )
        config = chart._resolve_chart_config()
        # The second configure_axis should override the first
        assert config.get("axis", {}).get("label_angle") == -90

    def test_configure_different_domains_accumulate(self, simple_df):
        """_resolve_chart_config line 282-288: axis and legend configs
        should both be present after accumulation."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_angle=-45)
            .configure_legend(orient="bottom")
        )
        config = chart._resolve_chart_config()
        assert "axis" in config
        assert "legend" in config
        assert config["axis"]["label_angle"] == -45
        assert config["legend"]["orient"] == "bottom"

    def test_configure_to_dict_omits_none(self):
        """Configure.to_dict recursion: None fields should be absent from output."""
        cfg = Configure(axis=AxisConfig(label_angle=-30))
        d = cfg.to_dict()
        assert "axis" in d
        assert "legend" not in d
        # Within axis, only label_angle should be present
        assert d["axis"]["label_angle"] == -30
        assert "label_color" not in d["axis"]

    def test_empty_configure_produces_empty_dict(self):
        """All-None Configure should produce an empty dict."""
        cfg = Configure()
        assert cfg.to_dict() == {}

    def test_configure_all_none_chart(self, simple_df):
        """Appending an empty Configure should not break rendering."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure()
        )
        config = chart._resolve_chart_config()
        # Should be empty since all params were None
        assert config == {} or all(v == {} for v in config.values() if isinstance(v, dict))

    def test_axis_x_and_axis_y_separate_in_configure(self, simple_df):
        """Chart.configure() with axis_x and axis_y should produce separate entries."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure(
                axis_x=AxisConfig(label_angle=-45),
                axis_y=AxisConfig(label_angle=0),
            )
        )
        config = chart._resolve_chart_config()
        assert config.get("axis_x", {}).get("label_angle") == -45
        assert config.get("axis_y", {}).get("label_angle") == 0


# ===================================================================
# Category: Configure with figure-level functions
# ===================================================================


class TestConfigureWithFigureFunctions:
    """Tests that configure() works on charts returned by figure-level functions.
    These test the interaction path: figure function -> Chart -> configure_*().
    """

    def test_displot_then_configure_axis(self, iris_df):
        """displot returns Chart; calling configure_axis on it should not error."""
        chart = fm.displot(iris_df, x="sepal_length")
        chart = chart.configure_axis(label_angle=-45)
        svg = chart.show_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_catplot_then_configure_legend(self, cat_df):  # BUG: catplot box with int column fails: ValueError stat_box_stats column must be Float64
        """catplot returns Chart; calling configure_legend on it should work.
        BUG: when cat_df has integer 'value' column, catplot(kind='box') fails
        because the Rust box_stats transform requires Float64 but catplot does
        not auto-cast integer value columns to float."""
        chart = fm.catplot(cat_df, x="group", y="value", kind="box")
        chart = chart.configure_legend(orient="bottom")
        svg = chart.show_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_displot_kde_then_configure_grid(self, iris_df):
        """KDE displot + configure_grid should not break the layered chart."""
        chart = fm.displot(iris_df, x="sepal_length", kind="kde")
        chart = chart.configure_grid(x=True, y=False, color="#ddd")
        svg = chart.show_svg()
        assert "<svg" in svg

    def test_relplot_then_configure_title(self, simple_df):
        """relplot + configure_title should work."""
        chart = fm.relplot(simple_df, x="x", y="y")
        chart = chart.configure_title(font_size=20, anchor="start")
        svg = chart.show_svg()
        assert "<svg" in svg

    def test_displot_stacked_then_configure_color(self, iris_df):
        """displot with stacked hue + configure_color should work."""
        chart = fm.displot(iris_df, x="sepal_length", hue="species", multiple="stack")
        chart = chart.configure_color(scheme="tableau10")
        svg = chart.show_svg()
        assert "<svg" in svg

    def test_catplot_strip_then_configure_padding(self, cat_df):
        """catplot strip + configure_padding should not break."""
        chart = fm.catplot(cat_df, x="group", y="value", kind="strip")
        chart = chart.configure_padding(top=20, bottom=20, left=40, right=40)
        svg = chart.show_svg()
        assert "<svg" in svg

    def test_lmplot_then_configure(self, simple_df):
        """lmplot (layered) + full configure() with AxisConfig should work."""
        chart = fm.lmplot(simple_df, x="x", y="y", ci=None, show_metrics=False)
        chart = chart.configure(
            axis=AxisConfig(label_angle=-30, grid=True),
            legend=LegendConfig(orient="none"),
        )
        svg = chart.show_svg()
        assert "<svg" in svg
        assert "NaN" not in svg


# ===================================================================
# Category: Annotations on figure-level charts
# ===================================================================


class TestAnnotationsOnFigureCharts:
    """Tests that annotations can be composed onto charts returned by
    figure-level functions via the + operator (chart.py __add__ line 4039-4057).
    """

    def test_displot_plus_text_annotation(self, iris_df):
        """chart.py __add__ line 4039-4041: Annotate container dispatch."""
        chart = fm.displot(iris_df, x="sepal_length")
        annotated = chart + Annotate(ann.text(5.0, 5.0, "Peak"))
        config = annotated._resolve_chart_config()
        assert "annotations" in config
        assert len(config["annotations"]) == 1
        assert config["annotations"][0]["type"] == "text"

    def test_displot_plus_bare_annotation_primitive(self, iris_df):
        """chart.py __add__ line 4044-4057: bare annotation primitive wraps in Annotate."""
        chart = fm.displot(iris_df, x="sepal_length")
        annotated = chart + ann.text(5.0, 5.0, "Peak")
        config = annotated._resolve_chart_config()
        assert "annotations" in config
        assert len(config["annotations"]) == 1

    def test_multiple_annotations_accumulate(self, simple_df):
        """chart.py __add__ line 4040: each + appends to _annotations list."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + ann.text(1.0, 2.0, "A") + ann.text(3.0, 4.0, "B")
        config = chart._resolve_chart_config()
        assert len(config["annotations"]) == 2

    def test_annotation_span_on_catplot(self, cat_df):
        """Annotations on a catplot (composite mark) chart."""
        chart = fm.catplot(cat_df, x="group", y="value", kind="box")
        chart = chart + ann.span("y", 0, 5, fill="#eee", opacity=0.2)
        config = chart._resolve_chart_config()
        assert any(a["type"] == "span" for a in config["annotations"])

    def test_annotation_arrow_coords(self, simple_df):
        """Arrow annotation with data-space coordinates serializes correctly."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + ann.arrow(1.0, 2.0, 3.0, 4.0, stroke="red")
        config = chart._resolve_chart_config()
        arrow_ann = config["annotations"][0]
        assert arrow_ann["type"] == "arrow"
        assert arrow_ann["x"] == 1.0
        assert arrow_ann["stroke"] == "red"

    def test_annotation_with_pixel_coords(self, simple_df):
        """PixelCoord values serialize as {"px": value} dicts."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + ann.text(ann.px(50), ann.px(100), "Label")
        config = chart._resolve_chart_config()
        text_ann = config["annotations"][0]
        assert text_ann["x"] == {"px": 50}
        assert text_ann["y"] == {"px": 100}

    def test_annotation_with_norm_coords(self, simple_df):
        """NormCoord values serialize as {"norm": value} dicts."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + ann.text(ann.norm(0.5), ann.norm(0.9), "Centered")
        config = chart._resolve_chart_config()
        text_ann = config["annotations"][0]
        assert text_ann["x"] == {"norm": 0.5}
        assert text_ann["y"] == {"norm": 0.9}

    def test_annotation_list_in_annotate_container(self, simple_df):
        """Annotate container with a list of primitives serializes all items."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + Annotate([
            ann.text(1.0, 2.0, "A"),
            ann.rect(0, 0, 2, 3, fill="blue", opacity=0.1),
            ann.line(0, 0, 5, 5),
        ])
        config = chart._resolve_chart_config()
        assert len(config["annotations"]) == 3
        types = {a["type"] for a in config["annotations"]}
        assert types == {"text", "rect", "line"}


