class TestStructuralFeatures:
    """Tests targeting structural features: SecondaryY, BreakAxis, Inset.
    Composition via __add__ (chart.py line 4059-4063).
    Serialization via _serialize_structural (_render.py line 298-365).
    """

    def test_secondary_y_composition(self, simple_df):
        """chart.py __add__ line 4059-4063: SecondaryY appends to _structural."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + SecondaryY(field="y", mark="line", color="red")
        assert len(chart._structural) == 1

    def test_secondary_y_serialization(self, simple_df):
        """_render.py _serialize_structural line 303-309: SecondaryY to dict."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + SecondaryY(field="y", mark="line", color="red", opacity=0.5)
        config = chart._resolve_chart_config()
        assert "structural" in config
        s = config["structural"][0]
        assert s["type"] == "secondary_y"
        assert s["field"] == "y"
        assert s["color"] == "red"
        assert s["opacity"] == 0.5

    def test_break_axis_single_gap_serialization(self, simple_df):
        """_render.py _serialize_structural line 310-327: single (start, end) tuple."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + BreakAxis(axis="y", gap=(10, 20))
        config = chart._resolve_chart_config()
        s = config["structural"][0]
        assert s["type"] == "break_axis"
        assert s["gaps"] == [[10, 20]]

    def test_break_axis_multiple_gaps_serialization(self, simple_df):
        """_render.py _serialize_structural line 310-327: list of gap tuples."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + BreakAxis(axis="x", gap=[(5, 10), (20, 30)])
        config = chart._resolve_chart_config()
        s = config["structural"][0]
        assert s["gaps"] == [[5, 10], [20, 30]]

    def test_inset_serialization_renders_inner_chart(self, simple_df):
        """_render.py _serialize_structural line 328-363: Inset renders inner chart to SVG."""
        inner = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        outer = fm.Chart(simple_df).mark_line().encode(x="x", y="y")
        outer = outer + Inset(
            chart=inner,
            bounds=(0.6, 0.1, 0.95, 0.5),
            border=True,
        )
        config = outer._resolve_chart_config()
        s = config["structural"][0]
        assert s["type"] == "inset"
        assert "<svg" in s["svg"]
        assert s["border"] is True
        assert s["bounds"] == [0.6, 0.1, 0.95, 0.5]

    def test_inset_with_norm_coords(self, simple_df):
        """_render.py _inset_coord: NormCoord should extract .value."""
        inner = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        outer = fm.Chart(simple_df).mark_line().encode(x="x", y="y")
        outer = outer + Inset(
            chart=inner,
            bounds=(ann.norm(0.1), ann.norm(0.1), ann.norm(0.9), ann.norm(0.9)),
        )
        config = outer._resolve_chart_config()
        s = config["structural"][0]
        assert s["bounds"] == [0.1, 0.1, 0.9, 0.9]

    def test_inset_with_pixel_coords_raises(self, simple_df):
        """_render.py _inset_coord line 342-345: PixelCoord not supported for Inset bounds."""
        inner = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        outer = fm.Chart(simple_df).mark_line().encode(x="x", y="y")
        outer = outer + Inset(
            chart=inner,
            bounds=(ann.px(50), ann.px(50), ann.px(200), ann.px(200)),
        )
        with pytest.raises(TypeError, match="px"):
            outer._resolve_chart_config()

    def test_multiple_structural_features_accumulate(self, simple_df):
        """chart.py __add__ line 4062: each + appends to _structural."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + SecondaryY(field="y", mark="line")
        chart = chart + BreakAxis(axis="y", gap=(10, 20))
        assert len(chart._structural) == 2
        config = chart._resolve_chart_config()
        types = {s["type"] for s in config["structural"]}
        assert types == {"secondary_y", "break_axis"}


# ===================================================================
# Category: Combined configure + annotations + structural
# ===================================================================


class TestCompositionCorners:
    """Tests that all three composition types (configure, annotations, structural)
    can be stacked onto the same chart without interference.
    """

    def test_all_three_on_same_chart(self, simple_df):
        """All three composition types should coexist in _resolve_chart_config."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_angle=-45)
        )
        chart = chart + ann.text(1.0, 2.0, "label")
        chart = chart + SecondaryY(field="y", mark="line")
        config = chart._resolve_chart_config()
        assert "axis" in config
        assert "annotations" in config
        assert "structural" in config

    def test_configure_then_layer_preserves_configure(self, simple_df):
        """chart.py __add__ line 4134-4135: configure from RHS merges into LHS."""
        base = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_angle=-30)
        )
        overlay = (
            fm.Chart(simple_df)
            .mark_line()
            .encode(x="x", y="y")
            .configure_legend(orient="bottom")
        )
        combined = base + overlay
        config = combined._resolve_chart_config()
        assert config.get("axis", {}).get("label_angle") == -30
        assert config.get("legend", {}).get("orient") == "bottom"

    def test_annotation_from_rhs_chart_merges(self, simple_df):
        """chart.py __add__ line 4137-4138: annotations from RHS merge into LHS."""
        lhs = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        lhs = lhs + ann.text(1.0, 2.0, "LHS label")
        rhs = fm.Chart(simple_df).mark_line().encode(x="x", y="y")
        rhs = rhs + ann.text(3.0, 4.0, "RHS label")
        combined = lhs + rhs
        config = combined._resolve_chart_config()
        assert len(config["annotations"]) == 2

    def test_structural_from_rhs_chart_merges(self, simple_df):
        """chart.py __add__ line 4139-4140: structural from RHS merge into LHS."""
        lhs = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        lhs = lhs + SecondaryY(field="y", mark="line")
        rhs = fm.Chart(simple_df).mark_line().encode(x="x", y="y")
        rhs = rhs + BreakAxis(axis="x", gap=(2, 4))
        combined = lhs + rhs
        assert len(combined._structural) == 2


# ===================================================================
# Category: Clone immutability
# ===================================================================


class TestCloneImmutability:
    """Tests that _clone (chart.py line 315-342) preserves all new slots
    and mutations don't alias.
    """

    def test_clone_preserves_configure(self, simple_df):
        """chart.py _clone line 338: _configure must be shallow-copied."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart.configure_axis(label_angle=-45)
        clone = chart._clone()
        assert len(clone._configure) == 1
        # Mutating clone's list should not affect original
        clone._configure.append(Configure())
        assert len(chart._configure) == 1

    def test_clone_preserves_annotations(self, simple_df):
        """chart.py _clone line 339: _annotations must be shallow-copied."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + ann.text(1.0, 2.0, "A")
        clone = chart._clone()
        assert len(clone._annotations) == 1
        clone._annotations.append(Annotate(ann.text(3.0, 4.0, "B")))
        assert len(chart._annotations) == 1

    def test_clone_preserves_structural(self, simple_df):
        """chart.py _clone line 340: _structural must be shallow-copied."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart + SecondaryY(field="y")
        clone = chart._clone()
        assert len(clone._structural) == 1
        clone._structural.append(BreakAxis(axis="x", gap=(1, 2)))
        assert len(chart._structural) == 1

    def test_clone_preserves_overrides(self, simple_df):
        """chart.py _clone line 341: _overrides must be shallow-copied."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        chart = chart.override(x_axis_label_angle=-45)
        clone = chart._clone()
        clone._overrides["new_key"] = 42
        assert "new_key" not in chart._overrides


