class TestNullNaN:
    """Tests with null and NaN values in figure-level functions."""

    def test_nan_in_displot_x_column(self):
        """NaN in the x column should not produce NaN in SVG."""
        df = pl.DataFrame({"x": [1.0, float("nan"), 3.0, 4.0, 5.0]})
        chart = fm.displot(df, x="x")
        svg = chart.show_svg()
        assert "<svg" in svg
        # NaN should not leak into SVG attributes
        assert "NaN" not in svg

