class TestAnnotateContainerEdgeCases:
    """Tests for Annotate container __post_init__ (container.py line 31-38)."""

    def test_annotate_single_item_wraps_in_list(self):
        """container.py __post_init__ line 34-35: single item auto-wrapped in list."""
        a = Annotate(ann.text(1.0, 2.0, "single"))
        assert isinstance(a.items, list)
        assert len(a.items) == 1

    def test_annotate_list_preserves_order(self):
        """container.py __post_init__ line 37: list items preserved in order."""
        items = [
            ann.text(1.0, 2.0, "first"),
            ann.text(3.0, 4.0, "second"),
        ]
        a = Annotate(items)
        assert len(a.items) == 2
        assert a.items[0].text == "first"
        assert a.items[1].text == "second"

    def test_annotate_list_does_not_alias_original(self):
        """container.py __post_init__ line 37: stores a fresh copy."""
        items = [ann.text(1.0, 2.0, "orig")]
        a = Annotate(items)
        items.append(ann.text(3.0, 4.0, "extra"))
        assert len(a.items) == 1  # not aliased

    def test_annotate_to_dict_list(self):
        """container.py to_dict_list line 41-42: each item's to_dict() called."""
        a = Annotate([ann.text(1.0, 2.0, "hi"), ann.rect(0, 0, 1, 1, fill="red")])
        dicts = a.to_dict_list()
        assert len(dicts) == 2
        assert dicts[0]["type"] == "text"
        assert dicts[1]["type"] == "rect"


