class TestDisplotEcdf:
    """Tests for displot kind='ecdf' edge cases."""

    def test_ecdf_without_x_raises(self):
        """distribution.py displot line 251: ecdf without x= raises ValueError."""
        df = pl.DataFrame({"y": [1.0, 2.0, 3.0]})
        with pytest.raises(ValueError, match="ecdf"):
            fm.displot(df, kind="ecdf")

    def test_ecdf_with_x_produces_svg(self, iris_df):
        """ECDF with x= should produce valid SVG."""
        chart = fm.displot(iris_df, x="sepal_length", kind="ecdf")
        svg = chart.show_svg()
        assert "<svg" in svg
        assert "NaN" not in svg


