# Category: displot size / aspect
# ===================================================================


class TestDisplotSizing:
    """Tests for displot height/aspect interaction."""

    def test_height_and_aspect(self, iris_df):
        """distribution.py displot line 321-324: width = height * aspect."""
        chart = fm.displot(iris_df, x="sepal_length", height=300, aspect=1.5)
        assert chart._height == 300
        assert chart._width == 450.0

    def test_height_only(self, iris_df):
        """height without aspect uses height as width."""
        chart = fm.displot(iris_df, x="sepal_length", height=400)
        assert chart._height == 400
        assert chart._width == 400  # width = height when aspect is None


